def backfill_from_audit_log(apps, schema_editor):
    """Fill `entered_by` on existing sales from the audit log, which has always named
    who created each one ("Sotuv" + create). Sales with no such line (imports, seed
    data) stay empty. The earliest line wins if a sale somehow has two."""
    AuditLog = apps.get_model("crm", "AuditLog")
    Sale = apps.get_model("crm", "Sale")
    creators = {}
    rows = (
        AuditLog.objects.filter(action="create", target_type="Sotuv",
                                target_id__isnull=False, user__isnull=False)
        .order_by("-created_at", "-pk")
        .values_list("target_id", "user_id")
    )
    for sale_pk, user_pk in rows.iterator():
        creators[sale_pk] = user_pk  # newest first, so the oldest is left standing
    sales = list(Sale.objects.filter(pk__in=creators, entered_by__isnull=True).only("pk"))
    for sale in sales:
        sale.entered_by_id = creators[sale.pk]
    Sale.objects.bulk_update(sales, ["entered_by"], batch_size=500)


